import{_ as s,a,b as t,c as i,d as n,e as r,f as o,g as d,h as l,i as c,j as p}from"./chunks/events.CxgAK881.js";import{_ as h,o as u,c as g,a3 as m}from"./chunks/framework.BlfGB29P.js";const T=JSON.parse('{"title":"USB Extender for Home Assistant","description":"Connect USB keys, Stream Decks and macro pads to up to three MQTT brokers. Illustrated installation, learning, topics and practical results.","frontmatter":{"title":"USB Extender for Home Assistant","description":"Connect USB keys, Stream Decks and macro pads to up to three MQTT brokers. Illustrated installation, learning, topics and practical results."},"headers":[],"relativePath":"en/projects/usb-extender/index.md","filePath":"en/projects/usb-extender/index.md","lastUpdated":1795291346000}'),k={name:"en/projects/usb-extender/index.md"};function b(y,e,f,v,w,F){return u(),g("div",null,[...e[0]||(e[0]=[m('<h1 id="usb-extender-for-home-assistant" tabindex="-1">USB Extender for Home Assistant <a class="header-anchor" href="#usb-extender-for-home-assistant" aria-label="Permalink to &quot;USB Extender for Home Assistant&quot;">​</a></h1><p><strong>0.1.22 · Public test release · Raspberry Pi · Updated 21 November 2026</strong></p><p>A USB keyboard connected to a Raspberry Pi can become a control panel for Home Assistant or ioBroker. USB Extender reads inputs and publishes them to up to <strong>three MQTT brokers simultaneously</strong>. Its configuration web interface can then be stopped; the USB/MQTT service continues independently.</p><p><a href="https://github.com/rockbaer2007/usb-extender-home-assistant" target="_blank" rel="noreferrer">GitHub / German and English README</a> · <a href="https://github.com/rockbaer2007/usb-extender-home-assistant/releases/tag/v0.1.22" target="_blank" rel="noreferrer">ZIP 0.1.22</a> · <a href="https://github.com/rockbaer2007/usb-extender-home-assistant/blob/master/CHANGELOG.md" target="_blank" rel="noreferrer">Changelog</a></p><p>This is a standalone Raspberry Pi program, not an HA app installed through the app store and not official Home Assistant or Elgato software. It is <strong>not a USB-over-IP tunnel</strong>: printers and cameras are not forwarded as remote USB devices.</p><p>The screenshots are supplied by the user from the real 0.1.5 setup. The interface currently uses German labels. Click wide images to open their original size.</p><p><a href="/images/usb-extender/key-list.png"><img src="'+s+'" alt="Wide key list with MQTT channel groups"></a></p><h2 id="hardware" tabindex="-1">Which devices are detected? <a class="header-anchor" href="#hardware" aria-label="Permalink to &quot;Which devices are detected? {#hardware}&quot;">​</a></h2><p><strong>Detected</strong> initially means that Linux can list the USB device. <strong>Usable</strong> also requires a driver that reads its input and your explicit permission in the app. Those are separate capabilities.</p><div class="ugso-table-scroll" tabindex="0"><table><thead><tr><th>Device</th><th>Implemented functionality</th><th>Verification</th></tr></thead><tbody><tr><td>USB keyboards, including Windows multimedia keyboards</td><td>Key codes, press/release, toggling switch, pressed state, click/double-click/hold</td><td>Trust/HCT keyboards used in the practical setup</td></tr><tr><td>Volume and media keys</td><td><code>KEY_VOLUMEUP</code>, <code>KEY_VOLUMEDOWN</code>, <code>KEY_MUTE</code>; other reported playback/track keys</td><td>Volume/mute observed; test other keys per model</td></tr><tr><td>HID macro pads and USB pedals</td><td>Same processing if Linux reports ordinary key codes</td><td>Model-dependent; reports welcome</td></tr><tr><td>Physical Elgato Stream Decks</td><td>Dedicated HID driver; display/input features below</td><td>Implemented; no physical Stream Deck tested in this project yet</td></tr><tr><td>Other LCD-key devices</td><td>Keyboard input may work through HID; displays need the appropriate vendor driver</td><td>No blanket compatibility claim</td></tr><tr><td>Printers, cameras, storage, audio interfaces, serial devices and other controllers</td><td>Inventory listing; specific functionality needs separate adapters</td><td>No general print/camera/audio/MIDI/serial forwarding</td></tr><tr><td>Stream Deck Mobile / Android app</td><td>Optional experimental network server with QR pairing, images and MQTT</td><td>User confirmed pairing, icon transfer, colours and an 8×8 grid; long-term stability still open</td></tr></tbody></table></div><p>A listed device is not automatically enabled. Under <strong>USB-Geräte</strong>, assign a name, select <strong>Gerät für Eingaben freigeben</strong>, and choose destination brokers. Devices without a serial number use their USB port for identification; moving them to another port may require assigning them again.</p><p><a href="/images/usb-extender/devices.png"><img src="'+a+`" alt="USB inventory and explicit input permission"></a></p><h2 id="installation" tabindex="-1">Install on the Pi <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Install on the Pi {#installation}&quot;">​</a></h2><p>Recommended: Raspberry Pi 4, Raspberry Pi OS Lite <strong>64-bit Bookworm or newer</strong>, Python 3.11+, systemd, sudo, and internet access for apt/PyPI. Multiple display devices may need a separately powered USB hub. 32-bit Pi OS has not been practically verified.</p><p>Copy the ZIP to the Pi, open a terminal in its download directory, and run:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt-get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt-get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> unzip</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">unzip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> USB-Extender-Home-Assistant-0.1.22-Raspi4.zip</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> USB-Extender-Home-Assistant-0.1.22</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install.sh</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>The installer shows nine steps, checks dependencies and installs missing packages. Updates back up existing data under <code>/var/backups/</code> and retain settings and icons. The ZIP is not a fully offline system image. For later updates, extract the new ZIP separately and run its installer.</p><p>Set a web password during initial setup; there is no installed default password. If necessary, run <code>sudo usb-extender password</code>. Then:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> usb-extender</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Open <code>http://&lt;pi-address&gt;:8098</code> in your browser and sign in. Replace screenshot example addresses with your own brokers. Use HTTP only in a trusted local network; otherwise put VPN/HTTPS in front. Do not expose the UI to the internet.</p><h2 id="setup" tabindex="-1">Configure brokers and learn keys <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Configure brokers and learn keys {#setup}&quot;">​</a></h2><ol><li>Under <strong>MQTT-Broker</strong>, enter host, port and any credentials. Enable wanted connections and save. Each broker has an independent connection; a key can use all three.</li><li>Enable discovery on HA brokers. For ioBroker select <strong>Aus – nur MQTT-Daten senden</strong> so its HA-discovery adapter does not complain about device triggers.</li><li>Under <strong>USB-Geräte</strong>, name and enable the device, choose its targets and save.</li><li>Under <strong>Tasten &amp; Anzeigen</strong>, select the device and click <strong>Anlernen starten</strong>. Press and release each wanted key once. Repeated or existing keys are not duplicated.</li><li>Select <strong>Anlernen beenden → Tasten übernehmen → Speichern</strong>. New rows are now active. During learning, the selected device does not send MQTT actions.</li><li>Change channel checkboxes, topics or names per row. <strong>Bearbeiten</strong> opens broker selection, switch behaviour and timing. New extra channels on existing rows initially remain off; newly learned rows have all channels prepared.</li></ol><p><a href="/images/usb-extender/brokers.png"><img src="`+t+'" alt="Three broker profiles in the practical setup"></a></p><p><a href="/images/usb-extender/learning.png"><img src="'+i+'" alt="Learning mode with the selected USB device"></a></p><p>If the browser closes during learning, the input pause expires within 15 seconds without further heartbeats. Learning drafts remain in the browser until applied and saved. Already saved assignments remain intact.</p><h2 id="topics" tabindex="-1">Topics and key functions <a class="header-anchor" href="#topics" aria-label="Permalink to &quot;Topics and key functions {#topics}&quot;">​</a></h2><p>Device name <strong>Trust1</strong> and key <strong>F1</strong> produce, for example, <code>trust1-key-f1/press</code>. Names are made MQTT-safe; German umlauts such as “Büro” become <code>buero</code>. Duplicate device names receive <code>-2</code>, <code>-3</code> etc. when needed. Saved topics remain stable after renaming and have the same name on every selected broker. Each can be edited.</p><div class="ugso-table-scroll" tabindex="0"><table><thead><tr><th>Suffix after <code>trust1-key-f1</code></th><th>Payload and function</th></tr></thead><tbody><tr><td><code>/press</code></td><td><code>press</code> immediately when pressed</td></tr><tr><td><code>/release</code></td><td><code>release</code> when released</td></tr><tr><td><code>/press-plus</code>, <code>/release-plus</code></td><td>Same action, then an empty message after 50 ms on that channel</td></tr><tr><td><code>/switch</code></td><td>First press <code>ON</code>, next press <code>OFF</code>; release does not change it</td></tr><tr><td><code>/state</code></td><td>Pressed <code>ON</code>, released <code>OFF</code></td></tr><tr><td><code>/button</code></td><td><code>click</code>, <code>double_click</code> or <code>hold</code>, depending on operation</td></tr><tr><td><code>/button-plus</code></td><td>Same button action, then empty after 50 ms</td></tr><tr><td><code>/click</code>, <code>/double-click</code>, <code>/hold</code></td><td>The respective individual gesture</td></tr></tbody></table></div><p>The word <code>plus</code> is used because <code>+</code> is an MQTT wildcard. All eleven channels can be enabled separately. Only plus channels are reset to empty; empty does <strong>not</strong> mean physical release. Switch values persist in <code>switches.json</code> across app restarts and are synchronized again after reconnection.</p><p><strong>Click/double-click/hold:</strong> A click waits for the double-click window (default 300 ms after release). A second click within it produces only <code>double_click</code>. Holding for 700 ms produces <code>hold</code> once, without a click on release. Holding the second press replaces the pending click sequence with hold. Times are adjustable per key. Native keyboard repeat is not another click or switch operation.</p><p><strong>Volume up/down:</strong> Active Press/Press+ channels can repeat while held, by default after 500 ms every 150 ms. Release stops repetition; a 30-second safety limit also applies. Your HA automation or ioBroker logic determines the volume step. Ordinary Press/Release channels remain immediate, independent of delayed button recognition.</p><p>Key messages use QoS 0 and no retain. Offline input is not replayed. Multiple active channels can trigger multiple mapped automations; select the channel appropriate for the intended single function.</p><h2 id="integration" tabindex="-1">Home Assistant and ioBroker <a class="header-anchor" href="#integration" aria-label="Permalink to &quot;Home Assistant and ioBroker {#integration}&quot;">​</a></h2><p>HA discovery groups all keys under the selected device name and one stable device identifier. Actions are device triggers with payload filters. Switch and pressed state are <strong>binary sensors</strong> showing state; controlling another device requires an automation or mapping.</p><img src="'+n+'" alt="HA shows Switch on and pressed state off after release" width="280"><p>In the user screenshot, Switch is <strong>on</strong> after operation, and pressed state is <strong>off</strong> after release. Unknown values can occur before the first received state message; that alone does not prove a broken input detector.</p><details><summary>Before the first state messages</summary><img src="'+r+'" alt="HA states before receiving the first key values" width="280"></details><p>In ioBroker, separate states appear below the MQTT adapter when each topic is first received. The practical screenshot shows simple values: <code>press</code>, <code>release</code>, <code>click</code>, <code>hold</code>, <code>ON</code> and <code>OFF</code>. Plus channels show <code>(null)</code> after their empty reset in this setup. That is expected; the state object remains. A double-click state appears only after an appropriate message is actually sent. Old state objects containing the former JSON event are not automatically changed. Discovery configuration messages intentionally remain JSON.</p><p><a href="/images/usb-extender/iobroker-states.png"><img src="'+o+'" alt="Separate ioBroker data points with simple values"></a></p><h2 id="stream-deck" tabindex="-1">Stream Deck and similar devices <a class="header-anchor" href="#stream-deck" aria-label="Permalink to &quot;Stream Deck and similar devices {#stream-deck}&quot;">​</a></h2><p>The integrated <code>python-elgato-streamdeck</code> 0.10.0 driver includes models such as Original/MK.2, Mini, XL, Neo, Pedal and Plus. This describes driver scope, <strong>not completed physical hardware testing</strong> by this project.</p><ul><li>Display keys: custom icons/text, device brightness, MQTT state feedback to change an icon, and targeted display commands.</li><li>Keys: Press/Release, click/double-click/hold, switch and pressed state as above.</li><li>Dials, where present: rotation direction and presses as input.</li><li>Touchscreen, where present: touch events; no freely designed touchscreen editor.</li><li>Pedal and other non-display models: input, but no display-key icons.</li><li>One fixed layout; profile/page switching remains open. Animated key icons are implemented.</li></ul><h3 id="editor" tabindex="-1">Graphical editor and compact key list <a class="header-anchor" href="#editor" aria-label="Permalink to &quot;Graphical editor and compact key list {#editor}&quot;">​</a></h3><p>The <strong>Stream Deck</strong> tab stays visible offline and retains its editor and last grid. Enable the device and save, then select a key to edit its label, icon, background image, text position and colours. The <strong>pressed</strong> state supports a second icon and separate text/background colours. Top/bottom labels reserve space beside the fitted icon. Previewing sends no MQTT action. Save afterwards.</p><p><a href="/images/usb-extender/editor-022.png"><img src="'+d+'" alt="Editor with a simulated deck"></a></p><p>This image is a <strong>local browser demo</strong>, not a hardware test. In <strong>Tasten &amp; Anzeigen</strong>, collapsed rows show <strong>Device – Key – Name</strong>; only one key is expanded at a time. <strong>Speichern</strong> saves all pending changes; <strong>Abbrechen</strong> discards changes to that key only. Indicators identify unsaved changes. <strong>Bearbeiten</strong> opens advanced MQTT and timing options.</p><h2 id="mobile" tabindex="-1">Stream Deck Mobile: optional and experimental <a class="header-anchor" href="#mobile" aria-label="Permalink to &quot;Stream Deck Mobile: optional and experimental {#mobile}&quot;">​</a></h2><ol><li>Enable <strong>Mobile-Server</strong>, enter the reachable Pi address and port (default <strong>28198</strong>) and save.</li><li>Choose <strong>Kopplung starten · QR-Code</strong> and scan using <strong>Add computer</strong> in Android.</li><li>Compare the six-digit fingerprint. Only if it matches, click <strong>Gerät vertrauen</strong> under <strong>Mobile-Verbindungen</strong>. Trust remains saved.</li><li>Open a deck in Android, enable the Mobile device in USB Extender and save. Assign its appearance and MQTT in the Stream Deck editor.</li><li><strong>Set rows and columns in Android.</strong> The editor follows the reported grid up to 8×8; there is no editor-side grid override.</li></ol><p>The Mobile service runs independently of the web service. Pairing requires the web interface; afterwards it may be stopped. A local WebSocket port is used, without cloud/Bonjour discovery or changes to the app&#39;s Pro purchase entitlement.</p><p><strong>Mobile-Verbindungen</strong> shows image/metadata counters, ping/pong and the last disconnect. For unchanged <strong>static</strong> keys, image counters should stop increasing. Keepalive maintains the connection without new images; animations intentionally send frames. The user confirmed pairing, icons, colours and 8×8. A longer idle test on an actual tablet remains open.</p><h2 id="icons" tabindex="-1">Icon library, animation and package import <a class="header-anchor" href="#icons" aria-label="Permalink to &quot;Icon library, animation and package import {#icons}&quot;">​</a></h2><p>Expand packages individually or search package names, filenames and subfolders. Hover/focus displays a filename and preview. 48×48 thumbnails use compact 52×52 tiles; the licence appears once in the package header. Free and total storage are shown in the page header.</p><p><a href="/images/usb-extender/icons-022.png"><img src="'+l+`" alt="Icon packages with preview, local browser demo"></a></p><p>Import individual images, browser folders, folders on the Pi, and local ZIP, <code>.streamDeckIconPack</code> or <code>.streamDeckPlugin</code> packages. Plugins contribute images from supported image folders only, never executable code. Supported JSON metadata provides the package name; otherwise the folder/archive name is used. Original filenames and subfolders are preserved. No automatic Marketplace download; respect usage rights.</p><p>PNG/JPEG and static SVGs are supported. GIF/WebP animate in <strong>normal and pressed</strong> states, up to 120 frames and 10 frames/s. SVG animation is not played; backgrounds remain static. Real hardware playback needs model-specific verification.</p><p>Originals: <code>/var/lib/ugso-usbhub/icons/IconPacks/</code>; index: <code>icons/index.json</code>; derived previews: <code>icons/.cache/</code>. Package deletion first creates a backup and blocks packages referenced by saved assignments.</p><p><strong>Since 0.1.22:</strong> Save the index once at the end and generate previews/animation data on demand. Browser folders upload as one ZIP, preserving multiple packages and their paths. Progress uses actual server processing counts. <strong>Finish an active import before installing an update.</strong></p><div class="ugso-table-scroll" tabindex="0"><table><thead><tr><th>Single local Windows PC comparison</th><th>Before</th><th>0.1.22</th></tr></thead><tbody><tr><td>Itsyhome, 240 real PNGs</td><td>4.262 s</td><td>0.395 s</td></tr><tr><td>6,800 synthetic PNGs</td><td>458.323 s</td><td>10.464 s</td></tr></tbody></table></div><p>Index writes: previously 240 or 6,800, now one per import. These are PC measurements, not Pi/SD-card timings. The user reported a 6,862-icon import stopping at 2,898. Its error message and installed version still need checking; successful processing of that package on the Pi is not confirmed.</p><p>For other similarly shaped devices, the keyboard part may already work through HID. LCDs, touch and vendor-specific commands may require a separate adapter. Please test and report an exact model rather than assuming full compatibility from its appearance.</p><h2 id="operation" tabindex="-1">Stop the web UI and back up <a class="header-anchor" href="#operation" aria-label="Permalink to &quot;Stop the web UI and back up {#operation}&quot;">​</a></h2><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> usb-extender</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> usb-extender</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> usb-extender</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> usb-extender</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> usb-extender</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> disable</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> usb-extender</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backup</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> journalctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ugso-usbhub</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 50</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p><code>web stop</code> closes the HTTP listener; merely closing the browser does not. The USB/MQTT service continues. Settings, icons and switch values live under <code>/var/lib/ugso-usbhub/</code>. The previous ten configuration versions are backed up automatically; a full CLI backup also includes icons and switch values. Do not upload backups publicly.</p><p><a href="/images/usb-extender/system.png"><img src="`+c+'" alt="System commands and diagnostics"></a></p><h2 id="tests" tabindex="-1">What has been demonstrated? <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;What has been demonstrated? {#tests}&quot;">​</a></h2><p>The user screenshots show 0.1.5, three broker profiles reporting online, learned function keys, HA states and individual ioBroker data points. The event list shows publication to HA, IOB and Testserver. That publication indication alone does not prove receipt at every broker; the HA/ioBroker screenshots provide additional visible evidence. This does not test every function on every device.</p><p><a href="/images/usb-extender/events.png"><img src="'+p+'" alt="F12 events with selected topics and three MQTT targets"></a></p><p>Version 0.1.22 passes 134 local Python tests plus JavaScript/DOM and Chrome checks for saving, mobile layout, packages, animation and folder upload. Local Mobile protocol tests complement these; they do not replace a tablet endurance test. Physical Stream Deck testing and a longer idle test with an 8×8 Mobile deck remain open.</p><h2 id="feedback" tabindex="-1">Test your hardware and send feedback <a class="header-anchor" href="#feedback" aria-label="Permalink to &quot;Test your hardware and send feedback {#feedback}&quot;">​</a></h2><p>Do you have a Stream Deck, similar LCD-key device, macro pad or USB pedal? Please test it and <a href="https://github.com/rockbaer2007/usb-extender-home-assistant/issues/new?template=hardware-test.yml" target="_blank" rel="noreferrer">report results on GitHub</a>. Bug reports and contributions are welcome.</p><p>Include model/revision, Pi model, OS and app version. Distinguish inventory listing from actual key codes. Report press/release, click/double-click/hold, icons/text, brightness, dials, touch and replug separately; explicitly mark untested features. Start with a harmless MQTT topic without real device actions. Inventory/event screenshots help. Do not publish passwords, tokens, <code>config.json</code> or backup archives.</p>',71)])])}const C=h(k,[["render",b]]);export{T as __pageData,C as default};
